using System.Security.Principal;
using WinGuardAgent.Storage;
namespace WinGuardAgent.Cli;
public static class AdminCli { public static async Task<int> RunAsync(string[] args){using var id=WindowsIdentity.GetCurrent();var p=new WindowsPrincipal(id);if(!p.IsInRole(WindowsBuiltInRole.Administrator)){Console.Error.WriteLine("WinGuard commands require an elevated Administrator terminal.");return 5;}var db=new Database();var policies=new PolicyRepository(db);await db.InitializeAsync();if(args.Length==0)return 0;switch(args[0].ToLowerInvariant()){case "status":Console.WriteLine("WinGuard database: "+Paths.Database);return 0;case "block-domain" when args.Length>1:await policies.AddDomainAsync(args[1]);Console.WriteLine("Blocked: "+args[1]);return 0;case "unblock-domain" when args.Length>1:await policies.RemoveDomainAsync(args[1]);Console.WriteLine("Unblocked: "+args[1]);return 0;case "block-app" when args.Length>1:await policies.AddAppAsync(args[1]);Console.WriteLine("Blocked app: "+args[1]);return 0;case "unblock-app" when args.Length>1:await policies.RemoveAppAsync(args[1]);Console.WriteLine("Unblocked app: "+args[1]);return 0;default:Console.WriteLine("Commands: status, block-domain <domain>, unblock-domain <domain>, block-app <exe>, unblock-app <exe>");return 1;}} }